import gsap from 'gsap';
import { useLayoutEffect, useRef } from 'react';

const PortfolioView = () => {
  const comp = useRef();

  useLayoutEffect(() => {
    let ctx = gsap.context(() => {
        const tl = gsap.timeline();

        // 1. Sidebar Anchor (Instant or fast fade)
        tl.fromTo('.sidebar-content', 
          { opacity: 0, x: -20 },
          { opacity: 1, x: 0, duration: 0.6, ease: 'power2.out' }
        );

        // 2. Methodology (The "How")
        tl.fromTo('.methodology-section',
          { opacity: 0, y: 30 },
          { opacity: 1, y: 0, duration: 0.8, ease: 'power2.out' },
          "-=0.4" // Overlap
        );

        // 3. Projects (The "Proof") - Staggered
        tl.fromTo('.project-card',
          { opacity: 0, y: 50, scale: 0.98 },
          { 
            opacity: 1, 
            y: 0, 
            scale: 1, 
            duration: 0.8, 
            stagger: 0.15, // The sequential bloom
            ease: 'back.out(1.2)' 
          },
          "-=0.4"
        );
    }, comp);

    return () => ctx.revert();
  },);

  return <div ref={comp}>...</div>;
}
